def process_input_and_find_optimal_color():
    n = int(input())
    cs = {}
    for i in range(n):
        a, c = map(int, input().split())
        if c in cs:
            cs[c].append(a)
        else:
            cs[c] = [a]

    optimal_color = -1
    max_min_deliciousness = 0
    for k in cs:
        m = min(cs[k])
        if m > max_min_deliciousness:
            optimal_color = k
            max_min_deliciousness = m
    return optimal_color
